export interface ConnectorConfig {
  notionApiKey: string
  notionDatabaseId: string
  fetch?: typeof fetch
}

export interface PipedriveDealPayload {
  meta: {
    action: string
    entity: string
    entity_id: string
    timestamp: string
    version: string
    webhook_id: string
    webhook_owner_id: string
    attempt: number
    host: string
  }
  data: {
    id: number
    title: string
    value: number
    currency: string
    owner_id: number
    won_time: string | null
    stage_id: number
    status: string
    add_time: string
    update_time: string
    person_id: number
    org_id: number
    pipeline_id: number
    expected_close_date: string
    close_time: string | null
    first_won_time: string | null
    lost_reason: string | null
    lost_time: string | null
    channel: string | null
    channel_id: string | null
    creator_user_id: number
    visible_to: string
    probability: number | null
    label_ids: number[]
    stage_change_time: string
    custom_fields: Record<string, unknown>
  }
  previous: unknown | null
}

export interface HandleResult {
  notionPageId: string
  notionPageUrl: string
}

function validatePayload(payload: unknown): asserts payload is PipedriveDealPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.meta || typeof p.meta !== 'object') {
    throw new Error('Invalid payload: missing meta object')
  }
  const meta = p.meta as Record<string, unknown>
  if (meta.action !== 'change' || meta.entity !== 'deal') {
    throw new Error('Invalid payload: not a deal change event')
  }
  if (!p.data || typeof p.data !== 'object') {
    throw new Error('Invalid payload: missing data object')
  }
  const data = p.data as Record<string, unknown>
  const requiredFields = ['title', 'value', 'owner_id'] as const
  for (const field of requiredFields) {
    if (!(field in data) || data[field] === null || data[field] === undefined) {
      throw new Error(`Missing required field: data.${field}`)
    }
  }
  if (data.status !== 'won') {
    throw new Error('Deal is not in won status')
  }
}

function extractCloseDate(data: PipedriveDealPayload['data']): string {
  const candidates = [data.won_time, data.close_time, data.first_won_time, data.update_time, data.stage_change_time]
  for (const candidate of candidates) {
    if (candidate) {
      return candidate.split('T')[0]
    }
  }
  throw new Error('Unable to determine close date: no valid timestamp found')
}

export async function handle(payload: unknown, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)
  const deal = payload as PipedriveDealPayload
  const data = deal.data

  const closeDate = extractCloseDate(data)

  const notionPayload = {
    parent: {
      database_id: config.notionDatabaseId
    },
    properties: {
      Title: {
        title: [
          {
            text: {
              content: data.title
            }
          }
        ]
      },
      Value: {
        number: data.value
      },
      Owner: {
        people: [
          String(data.owner_id)
        ]
      },
      'Close Date': {
        date: {
          start: closeDate
        }
      }
    }
  }

  const fetchImpl = config.fetch ?? fetch
  const response = await fetchImpl('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.notionApiKey}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28'
    },
    body: JSON.stringify(notionPayload)
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Notion API error: ${response.status} ${response.statusText} for POST https://api.notion.com/v1/pages - ${errorText}`)
  }

  const result = await response.json() as { id: string; url: string }
  return {
    notionPageId: result.id,
    notionPageUrl: result.url
  }
}

