    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      notionApiKey: 'test-notion-key',
      notionDatabaseId: 'test-database-id',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as PipedriveDealPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.notionPageId).toBe('page-id-generated-by-notion')
    expect(result.notionPageUrl).toBe('https://www.notion.so/workspace/page-id-generated-by-notion')
  })
})

